  const day = loginBonusPeriodKey(now);
  const sameDay = cur.day === day;
  const daily = sameDay ? { ...cur.daily } : {};
  const dailyTotal = sameDay ? cur.dailyTotal : 0;
  if (!action) return { changed: false, state: { ...cur, day, daily, dailyTotal }, gained: 0 };
