  const [dailyMasuAdvice, setDailyMasuAdvice] = useState(null); // null / { debugCount:null|number, eligible:boolean }
  const dailyMasuAdviceCheckedRef = useRef(false);
  // マーケットのアイテムの効果説明。カードを小さくしたぶん、詳細ボタンから出す
