  const [showWaveDetails, setShowWaveDetails] = useState(false);
  const [waveScanPreview, setWaveScanPreview] = useState(null);
  const difficultyCarouselRef = useRef(null);
  // 起動UIはゲーム本体と別の明示的な状態機械で管理する。
