  const [skipResult, setSkipResult] = useState(null);   // スキップ専用リザルトの内容
  const [skipAnimPhase, setSkipAnimPhase] = useState(0);
  const skipProcessingRef = useRef(false);
  const [currentPickingMon, setCurrentPickingMon] = useState(null);
