  const chooseTrainingBranch=id=>{if(!trainingSession.branchOptions.includes(id))return;Audio_.se.trainingDecide();advanceTraining(trainingSession,trainingSession.movementRemaining,id);};
  const trainingToolAvailability=id=>{if(['noReturn','returnCharm'].includes(id))return {ok:false,reason:'取得後に自動で待機し、条件を満たすと発動します'};if(id==='reroll')return trainingSession?.rollPending?{ok:true}:{ok:false,reason:'サイコロの出目確定後、移動前のみ使用可能'};if(trainingMovingRef.current||trainingSession?.movementRemaining||trainingSession?.branchOptions.length||trainingSession?.rollPending)return {ok:false,reason:'移動していない時のみ使用可能'};return {ok:true};};
  const useTrainingTool=id=>{const t=TRAINING_TOOLS[id],availability=trainingToolAvailability(id);if(!t||!availability.ok)return;const tools=[...trainingSession.tools];tools.splice(tools.indexOf(id),1);let effects={...trainingSession.effects},remainingTurns=trainingSession.remainingTurns;if(id==='sand')remainingTurns++;else if(id==='reroll'){const next={...trainingSession,tools,rollPending:false};Audio_.se.trainingTool();setTrainingSession(next);setTimeout(()=>rollTrainingDice(null,true,next),0);return;}else effects[id]=true;Audio_.se.trainingTool();patchTraining({tools,effects,remainingTurns,eventLog:logTraining(trainingSession,`${t.name}使用`)});};
  const restartTraining=()=>{if(trainingSelectedId){setTrainingMapScale(1);setTrainingMapOverview(false);setTrainingSession(createTrainingSession(trainingSelectedId));setGameState('TRAINING_BOARD');}};
  const leaveTrainingResult=()=>{setTrainingSession(null);setTrainingSelectedId(null);setGameState('DEBUG_SETTINGS');};
  // 染色もどき: マスモンの見た目の色(部位ごとにCSSフィルターで簡易パレットスワップ)を変える。
  // colorsはモンスターの染色可能な部位数と同じ長さの配列(各要素は色idまたはnull=染色しない)
  const useDyeItem = (masuId, colors) => {
    if ((ownedItems.dye_mock || 0) <= 0) return;
    const cleaned = (colors || []).map(c => (c && _resolveColorTarget(c)) ? c : null);
    if (!cleaned.some(Boolean)) return;
    setMasuMons(prev => {
      const next = prev.map(m => m.id === masuId ? { ...m, colors: cleaned, color: undefined } : m);
      storeSet('mh_masu_mons', next, false);
      return next;
    });
    setOwnedItems(prev => { const next = { ...prev, dye_mock: (prev.dye_mock || 0) - 1 }; storeSet('mh_owned_items', next, false); return next; });
    Audio_.se.tap();
  };
  // マスモンの名前を変更する(12文字まで)
  const renameMasuMon = (masuId, newName) => {
    const name = (newName || '').trim().slice(0, 12);
    if (!name) return;
    setMasuMons(prev => {
      const next = prev.map(m => m.id === masuId ? { ...m, name } : m);
      storeSet('mh_masu_mons', next, false);
      return next;
    });
  };
  // マスモンを削除する。編成に入っていた場合はその枠も取り除く
  const deleteMasuMon = (masuId) => {
    setMasuMons(prev => {
      const next = prev.filter(m => m.id !== masuId);
      storeSet('mh_masu_mons', next, false);
      return next;
    });
    const entry = 'masu:' + masuId;
    setMonsterRosterIds(prev => {
      if (!prev.includes(entry)) return prev;
      const next = prev.filter(x => x !== entry);
      storeSet('mh_monster_roster', next, false);
      return next;
    });
  };
  // 合体: 副の絆経験値(累計bondXp)をまるごと主に加算し、副は消滅させる。
  // 技を引き継がなければ無料、引き継ぐ場合は3000ダイヤ。副が絆Lv30以上で
  // fusionInheritUniqueがtrueなら、副の固有技を「継承した固有技」としてinheritedUniquesに記録する。
  // 能力値・距離適性・副の強化ポイントは引き継がないが、絆レベルが上がったぶんの
  // 強化ポイントは通常のレベルアップと同じように主へ配る。
  const executeMasuFusion = () => {
    if (fusionProcessingRef.current) return null;
    fusionProcessingRef.current = true;
    const main = getMasuMon(fusionMainId);
    const sub = getMasuMon(fusionSubId);
    if (!main || !sub || main.id === sub.id) { fusionProcessingRef.current=false; return null; }
    // レベルは必ず上限(levelCap)を通したものを使う。上限を超えた絆経験値がそのまま
    // レベルとして扱われると、費用が高くなったり上がらないレベルぶんの強化ポイントを
    // 配ってしまう(確認画面が「Lv.41になる」と出ていたのがこれ)
    const mainLvl = masuBondLevelInfo(main);
    const subLvl = masuBondLevelInfo(sub);
    const cost = masuFusionCost(mainLvl.level, subLvl.level, fusionInheritUnique);
    if (gold < cost) { fusionProcessingRef.current=false; return null; }
    const gainedXp = cappedBondXp(sub);
    const afterXp = cappedBondXp(main, gainedXp);
    const before = mainLvl;
    const after = bondLevelInfo(afterXp);
    const gainedLevels = after.level - before.level;
    const subBase = ALL_PLAYER_MONSTERS[sub.baseId];
    const mainBase = ALL_PLAYER_MONSTERS[main.baseId];
    const ownedUniqueIds = new Set([uniqueLineageId(mainBase?.unique, mainBase?.id), ...(main.inheritedUniques || []).map(unique=>uniqueLineageId(unique))].filter(Boolean));
    const subUniqueLineageId = uniqueLineageId(subBase?.unique, subBase?.id);
    const canInherit = subLvl.level >= FUSION_INHERIT_MIN_SUB_LEVEL && fusionInheritUnique && subBase?.unique && !ownedUniqueIds.has(subUniqueLineageId);
    const inheritedLevel = Math.max(0, Number(sub.uniqueSkillLevels?.own) || Number(subBase?.unique?.evoLevel) || 0);
    const inheritedUnique = canInherit ? { ...uniqueSkillAtLevel(subBase.unique, inheritedLevel), monId: subBase.id, lineageId:subUniqueLineageId, sourceMasuName: sub.name } : null;
    const historyEntry = { subName: sub.name, subBaseId: sub.baseId, subBondLevel: subLvl.level, xpGained: gainedXp, inherited: !!inheritedUnique, timestamp: Date.now() };
    setMasuMons(prev => {
      const next = prev
        .filter(m => m.id !== sub.id)
        .map(m => {
          if (m.id !== main.id) return m;
          const advanced = applyBondXpGain(m, gainedXp);
          return {
            ...advanced.masu,
            fusionBondLevels: donationDiamondValue(m.fusionBondLevels) + advanced.gainedLevels,
            fusionHistory: [...(m.fusionHistory || []), historyEntry],
            ...(inheritedUnique ? { inheritedUniques: [...(m.inheritedUniques || []), inheritedUnique] } : {}),
          };
        });
      storeSet('mh_masu_mons', next, false);
      return next;
    });
    const subEntry = 'masu:' + sub.id;
    setMonsterRosterIds(prev => {
      if (!prev.includes(subEntry)) return prev;
      const next = prev.filter(x => x !== subEntry);
      storeSet('mh_monster_roster', next, false);
      return next;
    });
    const goldAfter = gold - cost;
    setGold(goldAfter);
    storeSet('mh_gold', goldAfter, false);
    return {
      mainName: main.name, mainIconUrl: mainBase?.iconUrl, mainBaseId: main.baseId, mainEmoji: mainBase?.emoji, mainColors: getMasuColors(main),
      subName: sub.name, subIconUrl: subBase?.iconUrl, subBaseId: sub.baseId, subEmoji: subBase?.emoji, subColors: getMasuColors(sub),
      before, after, gainedXp, gainedLevels, inherited: !!inheritedUnique, cost,
    };
  };
  const resetFusionFlow = () => {
    fusionProcessingRef.current=false; setFusionStep('main'); setFusionMainId(null); setFusionSubId(null); setFusionInheritUnique(false); setFusionAnimPhase(0); setFusionResultData(null);
  };
  const resetDonationFlow = () => { if (donationProcessingRef.current) return; setDonationSelectedId(null); setDonationResult(null); setDonationAnimation(null); setDonationError(''); };
  const getRebirthSkillChoices = (masu) => {
    const base = ALL_PLAYER_MONSTERS[masu.baseId];
    const own = base?.unique ? [{ key:'own', name:base.unique.name, unique:base.unique }] : [];
    return [...own, ...(masu.inheritedUniques || []).map((unique,index)=>({ key:`inh:${index}`, name:unique.name, unique }))]
      .map(choice=>({ ...choice, level:Math.max(0, Math.floor(Number(masu.uniqueSkillLevels?.[choice.key]) || 0)) }));
  };
  // 限界突破: レベルはそのままで上限だけ上げる
  const executeMasuBreakthrough = async () => {
    if (rebirthProcessingRef.current || !rebirthSelectedId) return;
    const masu = masuMonsRef.current.find(m=>String(m.id)===String(rebirthSelectedId));
    const result = buildMasuBreakthrough({ masu, skillKey:rebirthSkillKey, gold, psycheOwned:ownedItemCount(ownedItemsRef.current, BREAKTHROUGH_ITEM_ID) });
    if (!result.ok) { setRebirthError(result.reason); return; }
    rebirthProcessingRef.current = true;
    setRebirthError('');
    const next = masuMonsRef.current.map(m=>String(m.id)===String(masu.id)?result.nextMasu:m);
    // 虹のプシュケーは限界突破が成立したときだけ減らす。
    // 途中で失敗したら保存もstateも触らないので、誤って減ることはない
    const nextItems = { ...ownedItemsRef.current, [BREAKTHROUGH_ITEM_ID]: result.nextPsyche };
    try {
      await storeSet('mh_masu_mons', next, false);
      await storeSet('mh_gold', result.nextGold, false);
      await storeSet('mh_owned_items', nextItems, false);
      masuMonsRef.current = next;
      ownedItemsRef.current = nextItems;
      setMasuMons(next); setGold(result.nextGold); setOwnedItems(nextItems);
      const base = ALL_PLAYER_MONSTERS[masu.baseId];
      const skill = result.raisesSkill ? getRebirthSkillChoices(masu).find(choice=>choice.key===result.skillKey) : null;
      setRebirthAnimation({ masu:result.nextMasu, base, raisesSkill:result.raisesSkill, keptSkillPoints:result.keptSkillPoints,
        skillName:skill?.name || '固有技', skillLevel:result.skillLevel, gainedPoints:result.gainedPoints });
      setTimeout(()=>{ setRebirthAnimation(null); setRebirthSelectedId(null); setRebirthSkillKey(null); rebirthProcessingRef.current=false; }, 4100);
    } catch {
      rebirthProcessingRef.current=false;
      setRebirthError('限界突破のデータを保存できませんでした。もう一度お試しください。');
    }
  };
  // 転生: レベルを99ぶん返して、振った強化をすべて振り直す
  const executeMasuReincarnation = async () => {
    if (reincarnateProcessingRef.current || !reincarnateSelectedId) return;
    const masu = masuMonsRef.current.find(m=>String(m.id)===String(reincarnateSelectedId));
    const result = buildMasuReincarnation({ masu, skillKey:reincarnateSkillKey, gold });
    if (!result.ok) { setReincarnateError(result.reason); return; }
    reincarnateProcessingRef.current = true;
    setReincarnateError('');
    const next = masuMonsRef.current.map(m=>String(m.id)===String(masu.id)?result.nextMasu:m);
    try {
      await storeSet('mh_masu_mons', next, false);
      await storeSet('mh_gold', result.nextGold, false);
      masuMonsRef.current = next;
      setMasuMons(next); setGold(result.nextGold);
      const base = ALL_PLAYER_MONSTERS[masu.baseId];
      const skill = result.raisesSkill ? getRebirthSkillChoices(masu).find(choice=>choice.key===result.skillKey) : null;
      setReincarnateAnimation({ masu:result.nextMasu, base, raisesSkill:result.raisesSkill, keptSkillPoints:result.keptSkillPoints, skillName:skill?.name || '固有技', skillLevel:result.skillLevel, fromLevel:result.fromLevel, nextLevel:result.nextLevel, nextPoints:result.nextPoints });
      setTimeout(()=>{ setReincarnateAnimation(null); setReincarnateSelectedId(null); setReincarnateSkillKey(null); reincarnateProcessingRef.current=false; }, 4100);
    } catch {
      reincarnateProcessingRef.current=false;
      setReincarnateError('転生データを保存できませんでした。もう一度お試しください。');
    }
  };
  const executeMasuRegeneration = async () => {
    if (regenerationProcessingRef.current || !regenerationSelectedId) return;
    const base=ALL_PLAYER_MONSTERS[regenerationSelectedId];
    const cost=regenerationUsed ? REGENERATION_COST : 0;
    if (!base || gold < cost) return;
    regenerationProcessingRef.current=true; setRegenerationProcessing(true);
    try {
      const masu=buildRegeneratedMasu(base);
      const next=[...masuMonsRef.current,masu];
      await storeSet('mh_masu_mons',next,false);
      await storeSet('mh_gold',gold-cost,false);
      await storeSet('mh_temple_regeneration_used_v1',true,false);
      masuMonsRef.current=next; setMasuMons(next); setGold(gold-cost); setRegenerationUsed(true);
      setRegenerationResult({masu,base,cost});
    } finally { regenerationProcessingRef.current=false; setRegenerationProcessing(false); }
  };
  const executeMasuDonation = async () => {
    if (donationProcessingRef.current || !donationSelectedId) return;
    donationProcessingRef.current = true;
    setDonationProcessing(true);
    setDonationError('');
    try {
      // state更新前の連打でも同じ個体を再利用できないよう、同期参照からIDで再取得する。
      const result = buildMasuDonation({
        masuMons: masuMonsRef.current, targetId: donationSelectedId, gold,
        monsterRosterIds, draftMonsterRoster, unlockedMonsterIds,
        validBaseIds: Object.keys(ALL_PLAYER_MONSTERS), requiredCount: STARTER_MONSTER_IDS.length,
      });
      if (!result.ok) { setDonationError(result.reason); setDonationSelectedId(null); return; }
      masuMonsRef.current = result.nextMasuMons;
      await storeSet('mh_masu_mons', result.nextMasuMons, false);
      await storeSet('mh_gold', result.nextGold, false);
      const nextItems = { ...ownedItemsRef.current, [BREAKTHROUGH_ITEM_ID]:ownedItemCount(ownedItemsRef.current, BREAKTHROUGH_ITEM_ID) + result.psyche };
      await storeSet('mh_monster_roster', result.nextRoster, false);
      await storeSet('mh_owned_items', nextItems, false);
      ownedItemsRef.current=nextItems; setOwnedItems(nextItems);
      await saveMissionProgress('donation');
      setMasuMons(result.nextMasuMons);
      setGold(result.nextGold);
      setMonsterRosterIds(result.nextRoster);
      setDraftMonsterRoster(result.nextDraftRoster);
      if (fusionMainId === result.donated.id || fusionSubId === result.donated.id) resetFusionFlow();
      setMasuMonDetail(null);
      setDonationSelectedId(null);
      setDonationAnimation({ name: result.donated.name, baseId: result.donated.baseId, src: masuDisplayImageUrl(ALL_PLAYER_MONSTERS[result.donated.baseId]), colors: getMasuColors(result.donated), diamonds: result.diamonds, psyche:result.psyche });
      await wait(1500);
      setDonationAnimation(null);
      setDonationResult({ name: result.donated.name, diamonds: result.diamonds, psyche:result.psyche, gold: result.nextGold });
    } catch (error) {
      setDonationError('寄付データを保存できませんでした。もう一度お試しください。');
    } finally {
      donationProcessingRef.current = false;
      setDonationProcessing(false);
    }
  };
  // ラン終了画面: 今回のランで勇者モンに選んでいた(まだマスモン化していない)モンスター種を、
  // 今回のランで得た絆経験値をそのまま初期値として、名前を付けてマスモンとして登録する
  // ラン終了画面(CHAMPION/敗北/リタイア)共通: マスモン登録ボタン・登録済み表示
  const masuRegisterButtonNode = () => {
    if (!finalRewardSummary?.heroBondGain || finalRewardSummary.heroBondGain.masuId) return null;
    if (masuRegisteredThisRun) return <div className="text-[10px] text-pink-300 font-black mt-1 flex items-center justify-center gap-1 shrink-0"><Heart size={11}/>マスモンとして登録しました！</div>;
    // 見落とされやすいので、ただのボタンではなく枠つきの案内にして光らせる
    return (
      <div
        className="w-full max-w-xs mt-2 shrink-0 rounded-2xl border-2 p-2.5"
        style={{ borderColor:'#ec4899', backgroundColor:'rgba(236,72,153,0.12)', animation:'masuCallout 1.6s ease-in-out infinite' }}
      >
        <div className="flex items-center justify-center gap-1.5 mb-1">
          <span className="text-[8px] font-black text-white px-1.5 py-0.5 rounded-full" style={{ backgroundColor:'#ec4899', animation:'masuBadge 1.6s ease-in-out infinite' }}>登録できます</span>
          <span className="text-[10px] font-black text-pink-200">{mainHero?.name||'このモンスター'}をマスモンに！</span>
        </div>
        <div className="text-[8px] text-pink-100/80 font-bold leading-snug mb-2 text-center">今回ためた絆経験値をそのまま引き継いで、次のランからも育てられます</div>
        <button
          onClick={()=>{setMasuNameInput(mainHero?.name||''); setShowMasuRegisterModal(true);}}
          className="w-full text-white py-3 rounded-xl font-black text-xs uppercase shadow-lg flex items-center justify-center gap-2 active:scale-95"
          style={{ backgroundColor:'#db2777' }}
        ><Heart size={14}/>マスモンとして登録する</button>
      </div>
    );
  };
  const registerMasuMon = (name) => {
    if (!mainHero || mainHero.masuId) return null; // 既にマスモンの勇者は登録不要(既存インスタンスに加算済み)
    const base = ALL_PLAYER_MONSTERS[mainHero.id];
    if (!base) return null;
    const startXp = Math.min(finalRewardSummary?.heroBondGain?.xpGain || 0, totalBondXpForLevel(INITIAL_MASU_LEVEL_CAP));
    const startLevel = bondLevelInfo(startXp);
    const id = 'masu_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
    const masu = {
      id, baseId: mainHero.id,
      name: (name || base.name).trim().slice(0, 12) || base.name,
      bondXp: Math.min(startXp, totalBondXpForLevel(INITIAL_MASU_LEVEL_CAP)),
      rebirthCount: 0,
      levelCap: INITIAL_MASU_LEVEL_CAP,
      uniqueSkillLevels: {},
      distAptPoints: Math.max(0, startLevel.level - 1),
      distApt: [...(base.distAptitude || ['C','C','C','C'])],
      statPoints: { hp: 0, atk: 0, def: 0, guts: 0 },
      createdAt: Date.now(),
    };
    setMasuMons(prev => { const next = [...prev, masu]; storeSet('mh_masu_mons', next, false); return next; });
    setMasuRegisteredThisRun(true);
    return masu;
  };

  // クリアしたWAVE数に応じてブリーダー経験値・ゴールド・勇者モンの絆経験値をまとめて加算(端末保存)。
  // 最終リザルト画面(CHAMPION/敗北)に出す獲得内訳もここで組み立てる
  const awardRunRewards = async (wavesCleared) => {
    // awaitより前に同期ロックする。敗北effectとボタン連打が同時に到達しても報酬は一度だけ。
    if (rewardsAwardedRef.current) return;
    rewardsAwardedRef.current = true;
    // 前のランの値が残らないよう、報酬を配りはじめる時点でいったん空にする
    // (WAVEを1つもクリアできなかったランは下で早期に戻るため、ここで消しておく必要がある)
    postRunMasuMonsRef.current = null;
    runHeroBondLevelRef.current = null;
    // 敗北・リタイア時は未決着だった現在WAVEを「挑戦」にだけ数える。勝利WAVEは撃破時に記録済み。
    if (wavesCleared < wave) await saveMissionProgress('battle');
    if (wavesCleared <= 0) { setFinalRewardSummary({ quickMode: isQuickMode(runMode), breederXpGain: 0, breederLevelBefore: breederLevel, breederLevelAfter: breederLevel, goldBefore: gold, goldAfter: gold, heroBondGain: null, allyBondGains: [], waveHistory }); return; }
    const scoreMult = DIFFICULTY_SETTINGS[difficulty]?.score || 1.0;
    const goldMult = DIFFICULTY_SETTINGS[difficulty]?.gold || 1.0;

    // クイックモードは経験値とダイヤだけ1.5倍(スコア倍率は難易度のまま)
    const breederXpGain = xpForWavesClearedInMode(wavesCleared, scoreMult, runMode);
    const breederLevelBefore = levelInfo(breederXp);
    const nextXp = breederXp + breederXpGain;
    const breederLevelAfter = levelInfo(nextXp);
    setBreederXp(nextXp);
    storeSet('mh_breeder_xp', nextXp, false);
    const gainedLevels = breederLevelAfter.level - breederLevelBefore.level;
    if (gainedLevels > 0) {
      setBreederPoints(prev => { const next = prev + gainedLevels; storeSet('mh_breeder_points', next, false); return next; });
      // 配った総数も記録しておく(読み込み時の補填処理が二重に配らないようにするため)
      storeSet('mh_breeder_points_granted', Math.max(0, breederLevelAfter.level - 1), false);
    }

    const goldGain = goldForWavesClearedInMode(wavesCleared, goldMult, runMode);
    const goldBefore = gold;
    const goldAfter = gold + goldGain;
    setGold(goldAfter);
    storeSet('mh_gold', goldAfter, false);

    // 勇者モンの絆経験値: 既にマスモン化済み(masuIdあり)ならそのインスタンスへ直接加算して確定保存する。
    // まだマスモン化していないプレーンな種のままなら、加算先が無いため保存はせず(=絆レベルの概念自体が
    // プレーン種には存在しない)、獲得量だけを計算してラン終了画面に表示する。そこで「マスモンとして
    // 登録する」を選んだ場合にのみ、この獲得量を初期値として新しいマスモンが作られる(registerMasuMon参照)
    // バトルへ参加した供モンには勇者モンの1/2、モンスター編成内で参加しなかった控えのマスモンには
    // 1/4を加算する。勇者・参加・控えの区分と個体IDは先に一意化し、同じ個体へ重複付与しない。
    // 絆経験値はブリーダー経験値と倍率が違う(プロは絆3倍・ブリーダー1.5倍)ので専用の関数を通す
    const gain = bondXpForWavesClearedInMode(wavesCleared, scoreMult, runMode);
    const bondAwards = buildRunBondAwards({
      gain,
      heroMasuId: mainHero?.masuId,
      participantMasuIds: slots.filter(s => s?.masuId).map(s => s.masuId),
      monsterRosterIds,
      masuMons,
    });
    const awardByMasuId = new Map(bondAwards.map(award => [String(award.masuId), award]));
    // 表示用の獲得内訳は、setMasuMonsの更新関数(Reactが後で非同期に呼び出すため、この関数の続きの
    // 行が実行される時点ではまだ実行されているとは限らない)の中で計算するのではなく、現在のmasuMons
    // (getMasuMon)を直接読んでこの場で同期的に計算する。以前はupdater内でのみ計算していたため、
    // タイミングによって勇者モン自身の絆経験値欄がリザルト画面に出ないことがあった
    let heroBondGain = null;
    if (mainHero?.masuId) {
      const masu = getMasuMon(mainHero.masuId);
      const before = bondLevelInfo(masu?.bondXp || 0);
      const after = bondLevelInfo(cappedBondXp(masu || {}, gain));
      heroBondGain = { name: mainHero.masuName || mainHero.name, emoji: mainHero.emoji, iconUrl: mainHero.iconUrl, xpGain:Math.max(0,cappedBondXp(masu || {}, gain)-(masu?.bondXp||0)), levelBefore: before, levelAfter: after, masuId: mainHero.masuId };
    } else if (mainHero) {
      const before = bondLevelInfo(0);
      const after = bondLevelInfo(gain);
      heroBondGain = { name: mainHero.name, emoji: mainHero.emoji, iconUrl: mainHero.iconUrl, xpGain: gain, levelBefore: before, levelAfter: after, masuId: null };
    }
    const allyBondGains = bondAwards.filter(award => award.rate === 0.5 && award.showInResult).map(award => {
      const masuId = award.masuId;
      const masu = getMasuMon(masuId);
      if (!masu) return null;
      const before = masuBondLevelInfo(masu);
      const after = bondLevelInfo(cappedBondXp(masu, award.gain));
      return { name: masu.name, xpGain:Math.max(0,cappedBondXp(masu, award.gain)-(masu.bondXp||0)), levelBefore: before, levelAfter: after, masuId };
    }).filter(Boolean);

    if (bondAwards.length > 0) {
      // 加算後の配列をこの場で作る。setMasuMons の更新関数の中だけで作っていたころは、
      // 続けて走るランキング送信からは加算前の値しか見えなかった
      const next = (masuMonsRef.current || masuMons).map(m => {
        const award = awardByMasuId.get(String(m.id));
        if (!award) return m;
        return applyBondXpGain(m, award.gain).masu;
      });
      masuMonsRef.current = next;
      postRunMasuMonsRef.current = next;
      setMasuMons(next);
      storeSet('mh_masu_mons', next, false);
    }
    // 勇者モンがまだマスモンでないときは、このランでためた絆経験値ぶんの絆Lvを覚えておく。
    // ランキングにはこの値を送る(登録すればそのまま同じ絆Lvの個体になる)
    runHeroBondLevelRef.current = (heroBondGain && heroBondGain.masuId == null && heroBondGain.xpGain > 0)
      ? heroBondGain.levelAfter.level : null;

    setFinalRewardSummary({ quickMode: isQuickMode(runMode), breederXpGain, breederLevelBefore, breederLevelAfter, goldBefore, goldAfter, heroBondGain, allyBondGains, waveHistory });
  };

  // スキップ: チケットを1枚使い、その難易度をボスまで倒したのと同じ経験値・ダイヤを受け取る。
  // 経験値の計算は通常クリア(awardRunRewardsのWAVE10到達)とまったく同じ式を使う。
  // スコア・ランキング・クリア回数・ミッション進捗・マスモン登録は対象外(通常のクリアとは別扱い)。
  const SKIP_WAVES = 10;
  // スキップチケットはまとめて使える。使う枚数は必ず1〜所持数の範囲へ丸め、
  // 所持数を超えて消費したり0枚で実行したりしないようにする
  const skipMaxCount = (itemId) => Math.max(1, ownedItems[itemId] || 0);
  const clampSkipCount = (value, itemId) => Math.max(1, Math.min(skipMaxCount(itemId), Math.floor(Number(value) || 1)));
  const skipFlowCount = () => skipFlow ? clampSkipCount(skipFlow.count, skipFlow.itemId) : 1;
  const changeSkipCount = (value) => setSkipFlow(prev => prev ? { ...prev, count: clampSkipCount(value, prev.itemId) } : prev);
  const executeBattleSkip = async () => {
    // 連打でチケットが2枚消える・報酬が二重に入ることが無いよう、awaitより前に同期ロックする
    if (skipProcessingRef.current) return;
    const flow = skipFlow;
    const item = BREEDER_MARKET_ITEMS.find(i => i.id === flow?.itemId);
    if (!flow || !item || !flow.hero) return;
    if ((ownedItems[item.id] || 0) <= 0) return;
    // まとめて使う枚数。画面の値が壊れていても所持数を超えて消費しないよう、ここでも必ず丸める
    const count = clampSkipCount(flow.count, item.id);
    skipProcessingRef.current = true;
    try {
      const nextItems = { ...ownedItems, [item.id]: (ownedItems[item.id] || 0) - count };
      setOwnedItems(nextItems);
      await storeSet('mh_owned_items', nextItems, false);

      const scoreMult = DIFFICULTY_SETTINGS[flow.difficulty]?.score || 1.0;
      const goldMult = DIFFICULTY_SETTINGS[flow.difficulty]?.gold || 1.0;

      // ブリーダー経験値・ブリーダーポイント(枚数ぶんまとめて受け取る)
      const breederXpGain = xpForWavesCleared(SKIP_WAVES, scoreMult) * count;
      const breederLevelBefore = levelInfo(breederXp);
      const nextBreederXp = breederXp + breederXpGain;
      const breederLevelAfter = levelInfo(nextBreederXp);
      setBreederXp(nextBreederXp);
      await storeSet('mh_breeder_xp', nextBreederXp, false);
      const gainedBreederLevels = breederLevelAfter.level - breederLevelBefore.level;
      if (gainedBreederLevels > 0) {
        setBreederPoints(prev => { const next = prev + gainedBreederLevels; storeSet('mh_breeder_points', next, false); return next; });
        storeSet('mh_breeder_points_granted', Math.max(0, breederLevelAfter.level - 1), false);
      }

      // ダイヤ
      const goldGain = goldForWavesCleared(SKIP_WAVES, goldMult) * count;
      const goldBefore = gold;
      const goldAfter = gold + goldGain;
      setGold(goldAfter);
      await storeSet('mh_gold', goldAfter, false);

      // 絆経験値。勇者モン=満額、選んだ供モン=1/2、編成内で選ばなかったマスモン=1/4 も通常と同じ
      const gain = xpForWavesCleared(SKIP_WAVES, scoreMult) * count;
      const allies = (flow.allies || []).filter(Boolean);
      const bondAwards = buildRunBondAwards({
        gain,
        heroMasuId: flow.hero.masuId,
        participantMasuIds: allies.map(a => a.masuId).filter(Boolean),
        monsterRosterIds,
        masuMons,
      });
      const awardByMasuId = new Map(bondAwards.map(a => [String(a.masuId), a]));
      const bondGainOf = (masuId) => {
        const masu = getMasuMon(masuId);
        const award = awardByMasuId.get(String(masuId));
        if (!masu || !award) return null;
        const before = masuBondLevelInfo(masu);
        const afterXp = cappedBondXp(masu, award.gain);
        return { name: masu.name, xpGain: Math.max(0, afterXp - (masu.bondXp || 0)), levelBefore: before, levelAfter: bondLevelInfo(afterXp), masuId };
      };
      const heroBondGain = flow.hero.masuId ? bondGainOf(flow.hero.masuId) : null;
      const allyBondGains = allies.map(a => a.masuId ? bondGainOf(a.masuId) : null).filter(Boolean);
      if (bondAwards.length > 0) {
        setMasuMons(prev => {
          const next = prev.map(mon => {
            const award = awardByMasuId.get(String(mon.id));
            if (!award) return mon;
            const before = masuBondLevelInfo(mon);
            const afterXp = cappedBondXp(mon, award.gain);
            const after = bondLevelInfo(afterXp);
            return { ...mon, bondXp: afterXp, distAptPoints: (mon.distAptPoints || 0) + (after.level - before.level) };
          });
          storeSet('mh_masu_mons', next, false);
          return next;
        });
      }

      setSkipResult({
        difficulty: flow.difficulty, itemId: item.id, itemName: item.name, itemEmoji: item.emoji, count,
        heroName: flow.hero.masuName || flow.hero.name, heroImgUrl: flow.hero.imgUrl, heroEmoji: flow.hero.emoji,
        heroBaseId: flow.hero.id, heroColors: flow.hero.colors,
        heroIsMasu: !!flow.hero.masuId,
        breederXpGain, breederLevelBefore, breederLevelAfter, goldGain, goldBefore, goldAfter,
        heroBondGain, allyBondGains,
      });
      setSkipConfirmOpen(false);
      setSkipAnimPhase(0);
      setGameState('SKIP_RESULT');
      Audio_.se.levelUp();
      setTimeout(() => setSkipAnimPhase(1), 700);
    } finally {
      skipProcessingRef.current = false;
    }
  };
  const openBattleSkip = (difficultyKey) => {
    // スキップはクイックモード専用。画面側でも押せないようにしているが、
    // ここでも止めておく(チャレンジで使えるとスコアを出さずに報酬だけ取れてしまう)
    if (!isQuickMode(battleMode)) return;
    const itemId = SKIP_TICKETS[difficultyKey];
    if (!itemId || (ownedItems[itemId] || 0) <= 0) return;
    setSkipFlow({ difficulty: difficultyKey, itemId, hero: null, allies: [], count: 1 });
    setSkipPickTab('roster');
    setSkipConfirmOpen(false);
    setGameState('SKIP_PICK');
  };
  // 戻る先は「バトルを始めた入口の画面」。既存の入口からなら BATTLE_MENU、新しい入口からならモード別の難易度選択
  const closeBattleSkip = () => { setSkipFlow(null); setSkipConfirmOpen(false); setGameState(battleEntryStateRef.current); };
  // 同じ種を二重に選ばないための鍵(編成タブとベースモンタブで同じ種が並ぶため、種idで見る)
  const skipMonKey = (mon) => mon ? String(mon.id) : '';
  const skipPickMon = (mon) => {
    setSkipFlow(prev => {
      if (!prev) return prev;
      const chosen = [prev.hero, ...(prev.allies || [])].filter(Boolean);
      if (chosen.some(c => skipMonKey(c) === skipMonKey(mon))) return prev;
      if (!prev.hero) return { ...prev, hero: mon };
      if ((prev.allies || []).length >= 3) return prev;
      return { ...prev, allies: [...(prev.allies || []), mon] };
    });
  };
  const skipClearSlot = (index) => {
    setSkipFlow(prev => {
      if (!prev) return prev;
      if (index === 0) return { ...prev, hero: null, allies: [] }; // 勇者モンを外すと供モンも外す
      const allies = [...(prev.allies || [])];
      allies.splice(index - 1, 1);
      return { ...prev, allies };
    });
  };

  // Masterを含む最終WAVEのクリア回数も、報酬・ランキングとは独立した同期ロックで1回だけ記録する。
  // Reactのstate updater内で永続化すると開発時のStrict Modeでupdaterが再評価され得るため、
  // 保存する値をrefロック後に確定し、副作用をupdaterの外へ出す。
  // クリア報酬の虹のプシュケー。難易度ごとの個数は CLEAR_PSYCHE_REWARD が正本。
  // 所持数は他の消耗アイテムと同じ mh_owned_items へ足すので、新しい保存キーは作らない。
  // 獲得数はリザルトに出したいので finalRewardSummary へも足す(報酬付与のあとに走るため関数形で足す)
  const awardClearPsyche = async () => {
    const gain = clearPsycheReward(difficulty);
    if (gain <= 0) return 0;
    const nextItems = { ...ownedItemsRef.current, [BREAKTHROUGH_ITEM_ID]: ownedItemCount(ownedItemsRef.current, BREAKTHROUGH_ITEM_ID) + gain };
    ownedItemsRef.current = nextItems;
    setOwnedItems(nextItems);
    await storeSet('mh_owned_items', nextItems, false);
    setFinalRewardSummary(prev => ({ ...(prev || {}), psycheGain: gain }));
    return gain;
  };
  const recordClearOnce = async () => {
    if (clearRecordedRef.current) return;
    clearRecordedRef.current = true;
    // 虹のプシュケーはクリアしたときだけ配る。ここは「クリアを1周回に1回だけ記録する」入口で、
    // チャレンジ・クイックのどちらもここを通り、clearRecordedRef が連打も二重付与も止める。
    // 敗北・リタイア・スキップチケットはこの関数を通らないので配られない
    await awardClearPsyche();
    if (isQuickMode(runMode)) {
      const nextQuick = (quickClearCounts[difficulty] || 0) + 1;
      setQuickClearCounts(prev => ({ ...prev, [difficulty]: Math.max(prev[difficulty] || 0, nextQuick) }));
      await storeSet(clearCountKey(BATTLE_MODE_QUICK, difficulty), nextQuick, false);
      return;
    }
    // プロモードのクリア回数も専用キーへ。チャレンジの通算クリア数(初勝利判定にも使う)は動かさない
    if (isProMode(runMode)) {
      const nextPro = (proClearCounts[difficulty] || 0) + 1;
      setProClearCounts(prev => ({ ...prev, [difficulty]: Math.max(prev[difficulty] || 0, nextPro) }));
      await storeSet(clearCountKey(BATTLE_MODE_PRO, difficulty), nextPro, false);
      return;
    }
    // 通算ではじめての優勝かどうか(どの難易度も1度もクリアしていない状態からの1勝目)
    const clearedBefore = Object.values(clearCounts).reduce((sum, n) => sum + (Number(n) || 0), 0);
    if (clearedBefore === 0) setRunHighlights(prev => ({ ...prev, firstWin: true }));
    const nextCount = (clearCounts[difficulty] || 0) + 1;
    setClearCounts(prev => ({ ...prev, [difficulty]: Math.max(prev[difficulty] || 0, nextCount) }));
    if (nextCount === 1) setRunHighlights(prev => ({ ...prev, firstClear: true }));
    await storeSet(`mh_clears_${difficulty}`, nextCount, false);
  };

  // はじめての敗北かどうか。どの難易度も1度もクリアしていなければ「まだ勝ったことがない」
  useEffect(() => {
    if (hp > 0 || debugBattle) return;
    const clearedEver = Object.values(clearCounts).reduce((sum, n) => sum + (Number(n) || 0), 0) > 0;
    if (!clearedEver) setRunHighlights(prev => (prev.firstLose ? prev : { ...prev, firstLose: true }));
  }, [hp, debugBattle, clearCounts]);

  // Save score on game end (CHAMPION is awarded synchronously in handleNextWave instead, so its result screen never renders before the summary is ready)
  useEffect(() => {
    if (hp <= 0) {
      if (debugBattleRef.current) {
        if (!debugResultRef.current) {
          debugResultRef.current = true;
          setResultProcessing(false);
          setDebugOutcome('lose');
        }
        return;
      }
      if (runFinalizingRef.current) return;
      runFinalizingRef.current = true;
      setRunFinalizing(true);
      setResultProcessing(true);
      (async () => {
        // 経験値・ダイヤの付与は端末内で完結するので必ず先に行う。
        // 以前はスコア送信(全国ランキングへの通信)の完了を待ってから付与していたため、
        // 通信が遅い・不安定なときにリザルトの獲得内訳がなかなか表示されなかった。
        try {
          await awardRunRewards(Math.max(0, wave - 1));
        } catch (e) { console.error('[result] award rewards failed:', e && e.message ? e.message : e); }
        // リザルト自体は背面に表示するが、ランキング保存の成否が確定するまでは全面ロックを
        // 維持する。タイトル遷移や再挑戦で周回IDを先に更新させない。
        await submitRunScoreOnce();
        setResultProcessing(false);
      })();
    }
  }, [hp, gameState]);


  // 編成の中の「どれが勇者モンか」の判定。バトル画面で目印を出すために使う。
  // 1回のランに同じ種は1体しか入らないので、種idの一致で特定できる
  // (マスモンは名前を自由に付けられるため、名前で見分けることはできない)
  const isHeroSlotMon = (mon) => !!(mon && mainHero && mon.id === mainHero.id);
  // 勇者モンの特性で増える同時使用枚数(ハムの「連続攻撃」)。
  // 「勇者モンに選んだときだけ効く」特性なので、効いていることが画面から分かるように
  // 枚数表示の横にも出す。計算と表示で食い違わないよう、ここを唯一の出どころにする
  const heroCardBonus = useMemo(() => (mainHero?.id === 'Ham' ? 1 : 0), [mainHero]);
  const cardLimit = useMemo(() => {
    const allyCount = slots.filter(s => s !== null).length;
    let limit = 1;
    if (effectiveMaxGuts >= 180 && allyCount >= 3) limit = 3;
    else if (effectiveMaxGuts >= 120 && allyCount >= 2) limit = 2;
    limit += heroCardBonus;
    return limit;
  }, [effectiveMaxGuts, slots, heroCardBonus]);

  const getCardGuts = (card) => {
    if (!card) return 0;
    if (card.type === 'guard') return 0;
    if (['buff','debuff','heal','draw'].includes(card.type)) return card.guts || 20;
    let cost = 20;
    if (['atk','range_atk','unique'].includes(card.type)) {
      let actualBaseMult = 1.0, actualCurrentMult = 1.0, actualBaseGuts = 20;
      if (card.type === 'unique') { const level = card.evoLevel || 0; actualBaseMult = card.baseMult; actualCurrentMult = card.baseMult + (level * 0.5); actualBaseGuts = card.baseGuts; }
      else { actualCurrentMult = card.mult; actualBaseMult = card.baseMult; actualBaseGuts = card.baseGuts; }
      if (actualBaseMult > 0) { const increaseRate = actualCurrentMult / actualBaseMult; cost = Math.floor(actualBaseGuts * increaseRate); }
      // 中二病特性: 固有技使用のたびに永続で消費ガッツ+10%(重複可)
      if (card.type === 'unique' && (card.monId==='Ark'||card.monId==='Iblis')) cost = Math.floor(cost * (1 + 0.1*getPermaBuff('chuuniUniqueStack')));
    }
    if (getTurnBuff('zeroGuts', false) && ['atk','range_atk','unique'].includes(card.type)) cost = 0;
    cost = Math.floor(cost * getTurnBuff('gutsCostMult', 1.0));
    // 絶氷の楔は使用後のカードすべてを3%ずつ軽くする。重ねすぎても負倍率にならないよう10%を下限にする。
    cost = Math.floor(cost * Math.max(0.1, 1 - 0.03*getPermaBuff('snegurochkaGutsDiscountStacks')));
    return cost;
  };

  const resetAllState = () => ({
    score:0, wave:1, hp:500, maxHp:500, guts:50, maxGuts:100, atk:100, def:100,
    slots:[null,null,null,null], mainHero:null, hand:[], deck:[], graveyard:[],
    enemy:null, enemyDist:2, selectedCards:[], isBusy:false,
    monSelection:getActiveMonsterList(), ownedUniques:[], slotUniqueChoice:{}, slotUniqueLevelChoice:{}, inheritedUniqueEvo:{}, ownedTeachings:[],
    atkLevel:0, guardLevel:0, guardBonusCount:0, upgradePoints:0, turnCount:1,
    permaBuffs:{ autoHpRecovery:0.1 }, waveBuffs:{}, turnBuffs:{}, nextTurnBuffs:{},
    currentWaveDamage:0, waveDistDamage:[0,0,0,0], distDmgBonus:[0,0,0,0], distAptPct:[0,0,0,0], totalDistDamage:[0,0,0,0], totalAllDamage:0, totalRecoveryDelta:0, waveResult:null,
    focusedCard:null, enemyIntent:null, enemyLastIntent:null, enemyNextIntent:null, effect:null, finalRewardSummary:null, waveHistory:[], gaveUp:false
  });

  // 自動案内の優先順位判定でも使うため、描画部より前で確定する。
  const updateNoticeVisible = updateAvailable && (!latestBuild || latestBuild !== dismissedUpdateBuild);

  // 初回チュートリアル。HOMEを最初に開いたときだけ自動で始める。
  // デバッグから何度でも呼べるよう、開始と終了を関数に分けている
  // デバッグ: 名前入力のところから、はじめての案内を通しで見る(保存はしない)
  const startOnboardingPreview = () => {
    onboardingPreviewBackupRef.current = { name: breederName, icon: breederIcon };
    setOnboardingPreview(true);
    // 名前もアイコンもまだ決まっていない状態から見られるようにする
    setOnboardingName('');
    setOnboardingIcon(null);
    setAssistantDebug(null);
    setShowHelp(false);
    setGameState('PROFILE');
    setTutorialKind('intro');
    setTutorialStep(0);
  };
  // いま案内しているページが指している施設。HOMEでその建物だけを明るく強調する
  const tutorialSpot = (() => {
    if (tutorialStep == null || tutorialKind !== 'tour') return null;
    const pages = (typeof ASSISTANT_TUTORIAL !== 'undefined' && ASSISTANT_TUTORIAL) || [];
    return pages[tutorialStep]?.spot || null;
  })();
  const spotClass = (name) => (tutorialSpot === name ? ' is-tutorial-spot' : '');
  // 説明の吹き出しはふだん画面の下に出すが、光らせた場所が下のほうにあると
  // その上に重なって「どこの話か分からない」状態になる。実際の位置を測って上下を入れ替える
  const [tutorialPanelAtTop, setTutorialPanelAtTop] = useState(false);
  useEffect(() => {
    if (tutorialStep == null || !tutorialSpot) { setTutorialPanelAtTop(false); return; }
    // 光らせた要素が描かれてから測る
    const id = requestAnimationFrame(() => {
      try {
        const els = document.querySelectorAll('.is-tutorial-spot');
        const height = window.innerHeight || 0;
        let bottom = -Infinity;
        els.forEach(el => {
          // 施設は当たり判定の枠が広く、実際に見えているのは中のラベルなので、そちらを測る
          const target = el.classList.contains('mh-home-facility') ? (el.querySelector('span') || el) : el;
          const r = target.getBoundingClientRect();
          if (r.height > 0) bottom = Math.max(bottom, r.bottom);
        });
        setTutorialPanelAtTop(height > 0 && bottom > height * 0.5);
      } catch { setTutorialPanelAtTop(false); }
    });
    return () => cancelAnimationFrame(id);
  }, [tutorialStep, tutorialSpot]);
  const startTutorial = (kind = 'tour') => { tutorialShownRef.current = true; setShowTitleSettings(false); setTutorialKind(kind); setTutorialStep(0); };
  const finishTutorial = async (remember = true) => {
    const kind = tutorialKind;
    setTutorialStep(null);
    // 最初のあいさつを読み終えたら、名前とアイコンを決めるプロフィール画面へ進む
    if (kind === 'intro') { setGameState('PROFILE'); return; }
    if (kind === 'battleGuide') return;
    if (remember) { try { await storeSet(TUTORIAL_SEEN_KEY, true, false); } catch {} }
  };
  useEffect(() => {
    if (bootPhase !== 'GAME' || gameState !== 'HOME' || tutorialShownRef.current || !dataLoaded) return;
    tutorialShownRef.current = true;
    let cancelled = false;
    (async () => {
      const seen = await storeGet(TUTORIAL_SEEN_KEY, false, false);
      if (!cancelled && seen !== true) { setTutorialKind('tour'); setTutorialStep(0); }
    })();
    return () => { cancelled = true; };
  }, [bootPhase, gameState, dataLoaded]);

  // 既存の村案内とは別に、バトルチュートリアルをまだ完了していない人へ一度だけ案内する。
  // 初回プロフィール設定や村案内と重ならないよう、それらが閉じたHOMEで判定する。
  useEffect(() => {
    if (bootPhase !== 'GAME' || gameState !== 'HOME' || !dataLoaded || !onboarded || tutorialStep != null || battleTutorialGuideCheckedRef.current) return;
    battleTutorialGuideCheckedRef.current = true;
    let cancelled = false;
    (async () => {
      const [tourSeen, seen, shown] = await Promise.all([
        storeGet(TUTORIAL_SEEN_KEY, false, false),
        storeGet(BATTLE_TUTORIAL_SEEN_KEY, false, false),
        storeGet(BATTLE_TUTORIAL_GUIDE_SHOWN_KEY, false, false),
      ]);
      if (tourSeen !== true) { battleTutorialGuideCheckedRef.current = false; return; }
      if (cancelled || seen === true || shown === true) return;
      // 表示を決めた時点で記録し、「今は見ない」や再読込でも繰り返さない。
      await storeSet(BATTLE_TUTORIAL_GUIDE_SHOWN_KEY, true, false);
      if (!cancelled) { setTutorialKind('battleGuide'); setTutorialStep(0); }
    })();
    return () => { cancelled = true; };
  }, [bootPhase, gameState, dataLoaded, onboarded, tutorialStep]);

  // 初回案内・重要通知・ログインボーナスのすべてが閉じた後にだけ、日次アドバイスを出す。
